// Dijkstra (requires MinHeap class)
function dijkstra(graph, source, n) {
  // graph[u] = [[v, weight], ...]
  const dist = new Array(n).fill(Infinity);
  dist[source]=0;
  const heap = new MinHeap((a,b)=>a[0]-b[0]); // compare by distance
  heap.push([0, source]);

  while (heap.size()>0) {
    const [d, node] = heap.pop();
    if (d > dist[node]) continue; // stale entry check
    for (const [nb, w] of graph[node]) {
      const nd = dist[node]+w;
      if (nd < dist[nb]) { dist[nb]=nd; heap.push([nd, nb]); }
    }
  }
  return dist;
}

// Bellman-Ford
function bellmanFord(n, edges, source) {
  // edges: [[u, v, weight], ...]
  const dist = new Array(n).fill(Infinity);
  dist[source]=0;

  for (let i=0;i<n-1;i++) {
    let updated=false;
    for (const [u,v,w] of edges) {
      if (dist[u]!==Infinity && dist[u]+w < dist[v]) {
        dist[v]=dist[u]+w; updated=true;
      }
    }
    if (!updated) break; // early exit
  }

  // Vth pass: negative cycle detection
  for (const [u,v,w] of edges) {
    if (dist[u]!==Infinity && dist[u]+w < dist[v]) return null;
  }
  return dist;
}
